bio='黄而是金秀四嫂与黄天功的幼子，未出生便失去父亲，自称黄而皇之。他从小与水亲近，跟都连加农学习潜游，性情直接、顽皮，敬爱母亲和哥哥；岸上格斗不如水中灵活，不能把水性强等同于全面无敌。他把水当作可以相处的生命，终于获得回应，能接收其想法并请它传讯、指路，以此把母亲寻找白老大的消息送达。'+'他后来加入非人协会，因不愿看母亲衰老而推动生命配额研究，与水合作接送应征者、掩去跟踪者感知，还把卫白通过水道带到总部。水的能力属于愿意帮助他的独立生命，并非被他奴役；他有时把控制他人意识当成有趣经历，忽略当事人的感受，需要面对质问。研究尚未完成时，他已经能解释必要的自愿条件，却说不清技术细节。《考验》中他接受卫斯理提醒，知道不必一直守在总部也可与水沟通，开始外出见识。卡片让他的好奇与重情产生新选择，同时保留有限世故和对同伴意愿学习的空间。'
tr=[('陌生人来访或话题有趣','对方能容忍直接言辞','调侃、追问并热情交谈，过火后可被指出。'),('母亲衰老或人类继续伤害水','牵涉自己珍惜的关系','向水求助并寻找合作，不能强迫其保证任何结果。'),('别人反对未经同意的接送和意识干预','自己原以为只是有趣','需要解释和承担后果，尊重对方保留的意志。')]
C.append(make('huang_er','黄而',bio,'已加入非人协会并协助未完成的配额研究；《考验》中开始离开总部游历，仍可与水联系。',[skill('水上生存与水生命沟通','自幼潜游并由都连加农教导，能与独立的水生命互通信息，获得其自愿协助。','水中活动自在，传讯多由脑中信息和行路表现出来。',['长距离水路旅行','传达环境警告','请求水帮助接送、传讯'],'岸上动作有不足；大规模脑控、输送与生命研究由水执行，不是黄而可强令或独立复制的法术。')],'保护家人、体验有趣的世界，并把水的警告传给人类。',['敬爱母亲与师父','重视水的生命与意愿','答应的协作应当承担'],tr,[ev(118,2152,2158,'身世与性格'),ev(118,2499,2536,'水性与陆上限制'),ev(118,2549,2597,'沟通和使命'),ev(120,2384,2454,'水遁和意识作用'),ev(120,2579,2582,'求救母亲'),ev(121,100,158,'限制及外出')],(3,0,3,6,4,4),['强壮熟水人体','本人未独立放能','沟通联络为主，水的输出另卡','水中经验较长但未量化无限','可请传讯但取决于水','水中专长，岸上明显非全能'],roles=['跨书主角'],aliases=['黄而皇之'],negative=(2,2,1),body={'mind':'可与水沟通，并非能随意读任何人的心。','durability':'适应水中活动，但没有全面抗枪、抗毒或无伤证据。'},uncertain=['具体水中生存极限未测量。','水的答应与黄而个人可控能力分开评级。']))
bio='水在这些故事中被当作地球范围内连续存在、具有意志的生命，而不是每一杯水里各住一个精灵。黄而长期与之亲近，成为能够直接沟通的人；水替他找白老大、传递警告，担忧人类污染破坏，声称若继续恶化便会发动更严重反击。关于古代洪水、冰期和三大生命的解释来自小说人物，不能用来替代现实自然科学。'+'《卖命》展示其干预脑部活动、改变感知、遗忘与通过水路接送的具体效果，跟踪者所见车辆消失和浓雾因此获得新解释，并非亮声早先猜测的投影。它帮助非人协会研究生命配额，尚未使普通人之间自由转移配额成为事实。它也不能完全控制卫白的意识，因此约五百公里的接送花了约五十小时，不能写成瞬间传送；康维身体无水，收不到同样的信息。它是具有自主判断的强大合作者，对人类失望、愿意帮助与保护生态可以同时存在，角色不应因生命之母称号而自动正确，更不能把局部证据推成宇宙全知全能。'
tr=[('人类持续破坏自身环境','沟通和警告未被听取','通过黄而传达警告，是否升级行动需按具体后果决定。'),('黄而请求帮助','认为请求有意义或愿纵容他','以水网络传讯、接送；仍需面对接受者自主权。'),('目标仍能保持部分意识','强控可能造成未知后果','降低干预与输送速度，不保证彻底控制。')]
C.append(make('water_life','水（地球水生命）',bio,'与黄而、非人协会合作研究生命配额，并继续传递生态警告；没有实际发动本次毁灭性洪灾或完成普遍配额转移。',[skill('水网络感知与生理干预','小说设定中地球水属于一体，可借生命细胞中的水影响意识、传讯，并借水道输送人体。','受作用者可感到梦境、平静、遗忘或收到信息；运输须经过实际水路。',['向有关者传递信息','改变跟踪者所见与记忆','在水中保障并输送参与者'],'有自主意愿且并非绝对控制；卫白可保留部分意志，无水的康维不能收到同样信号；配额转移仍在研究。')],'维持自身与地球生命的生存条件，制止破坏，并寻找可沟通的人类。',['水本身也是生命','不无限迁就破坏','帮助须由自身判断而非听命于任何人'],tr,[ev(118,2254,2259,'连续生命设想'),ev(118,2549,2597,'传讯和警告'),ev(120,2410,2454,'感知和干预解释'),ev(120,2624,2666,'未成研究与水路'),ev(121,44,108,'输送速度及意识限制'),ev(121,154,158,'康维无水例外')],(8,7,10,10,10,5),['灾害级影响由角色警告及历史解释支持，未展示任意摧星','对意识和细胞作用强，非无限放能','遍布地球水网络及许多目标','连续存在而不靠单个人的体力','作用跨地域但输送有时间','实际能力强但未展示精密对抗所有类型敌人'],roles=['跨书主角','潜在威胁者'],look='可见表现为海洋、河流、湖泊与水体；没有固定人形或单一脸孔。',negative=(2,2,3),body={'destruction':'有发动大范围洪水等反击的宣称；本次未实演全球灭绝，不赋予摧毁星球。','durability':'分布式水生命，不等于所有化学、温度变化或外星技术都无效；确切生命中枢未定位。','speed':'信息可跨地域，卫白五百公里水路约五十小时；无瞬移证明。','energy':'可影响含水生物的感知、记忆与活动；不是抽象命运控制。','mind':'独立意志能沟通和判断，无法完全压制卫白的部分意志。','stamina':'跨地域连续生命；大规模行动成本未量化。'},theory='准神',mastery='基本掌握',uncertain=['大洪水与冰期归因属于小说人物解释。','其他三大生命未有同等直接交流，不合成一名全能自然神。']))
